/**
 * 从 path 的 d 属性估算一个能容纳全部内容的 viewBox 尺寸。
 *
 * ★ 为什么要自动算 ★
 *   品牌图标来源不一：simple-icons 用的是 0~24 坐标系，
 *   有些银行/机构的标志是 0~1024 坐标系。
 *   如果渲染时写死 viewBox="0 0 24 24"，1024 系坐标的图标
 *   会被裁到只剩左上角一小块（几乎看不见）。
 *   这里取所有坐标绝对值的最大值，向上取整，作为正方形的边长。
 *
 * @param {string[]} paths path 的 d 属性数组
 * @returns {number} viewBox 边长（最小 24）
 */
function estimateViewBoxSize(paths) {
  let max = 0
  for (const d of paths) {
    const nums = d.match(/-?\d*\.?\d+/g) || []
    for (const n of nums) {
      const v = Math.abs(Number(n))
      if (v > max) max = v
    }
  }
  // 向上取整到整数，至少 24（保证小图标不会被放大）
  return Math.max(24, Math.ceil(max))
}

/** 哪些 key 是品牌（填充），哪些是通用（描边） */
export const BRAND_ICON_KEYS = new Set(Object.keys(BRAND_PATHS))

/**
 * 取某个图标的 path 列表。
 *
 * @param {string} key 图标 key
 * @returns {string[]} path 的 d 属性数组
 */
export function accountIconPaths(key) {
  if (BRAND_PATHS[key]) return [BRAND_PATHS[key]]
  return LINE_PATHS[key] || []
}

/**
 * 判断某个 key 是不是品牌图标（品牌是填充的，通用是描边的）。
 *
 * @param {string} key 图标 key
 * @returns {boolean}
 */
export function isBrandIcon(key) {
  return !!BRAND_PATHS[key]
}

/**
 * 生成图标 SVG。
 *
 * ★ 品牌和通用的 SVG 结构不一样 ★
 *   品牌：fill=色值，fill-rule=evenodd（官方路径依赖它挖孔，
 *        少了这个参数，Mastercard 的两个圆会叠成实心块）
 *   通用：fill=none + stroke，标准的描边图标
 *
 * @param {string} key 图标 key
 * @param {object} opts { size, color }
 * @returns {string} SVG 源码
 */
export function accountIconSvg(key, opts = {}) {
  const size = Number(opts.size) > 0 ? Number(opts.size) : 24
  const color = opts.color || 'currentColor'
  const paths = accountIconPaths(key)
  if (!paths.length) return ''

  // viewBox 按 path 坐标系自动适配（24 系和 1024 系都能正确显示）
  const vb = estimateViewBoxSize(paths)
  const viewBox = `0 0 ${vb} ${vb}`

  if (isBrandIcon(key)) {
    const body = paths.map((d) => `<path d="${d}"/>`).join('')
    return (
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" ` +
      `width="${size}" height="${size}" fill="${color}" fill-rule="evenodd">` +
      body +
      `</svg>`
    )
  }

  const body = paths.map((d) => `<path d="${d}"/>`).join('')
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" ` +
    `width="${size}" height="${size}" fill="none" stroke="${color}" ` +
    `stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">` +
    body +
    `</svg>`
  )
}

/**
 * 生成 data URI（给 <image> 的 src 用）。
 *
 * ★ 颜色必须是真实色值 ★
 *   data URI 是独立图片文档，CSS 变量（var(--app-x)）在里面不存在，
 *   会让 stroke 变成无效值 -> 图标透明（这个坑踩过一次）。
 *
 * @param {string} key 图标 key
 * @param {object} opts { size, color }
 * @returns {string} data URI
 */
export function accountIconDataUri(key, opts = {}) {
  const svg = accountIconSvg(key, opts)
  if (!svg) return ''
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg)
}
